class Vehicle {
  let wheels: Int
  var name: String

  init(wheels: Int, name: String) {   // designated
    self.wheels = wheels
    self.name = name
  }

  convenience init(name: String) {    // convenience — delegates across
    self.init(wheels: 4, name: name)
  }

  required init(coder: Int) {         // every subclass must provide this
    wheels = 0
    name = "decoded"
  }
}

final class Truck: Vehicle {
  let payloadKg: Int

  init(payloadKg: Int, name: String) {
    self.payloadKg = payloadKg        // phase 1: own properties first
    super.init(wheels: 6, name: name) // then up the chain
    self.name = name.uppercased()     // phase 2: self is usable now
  }

  required init(coder: Int) {
    payloadKg = 0
    super.init(coder: coder)
  }
}

