}
let s1 = Session(token: "x"), s2 = Session(token: "x")
print(s1 == s2, s1 === s2)            // true false

@MainActor
protocol UploaderDelegate: AnyObject {          // ✅ class-bound, so weak is legal
  func uploader(_ uploader: Uploader, didProgress fraction: Double)
  func uploader(_ uploader: Uploader, didFinish url: URL)
  func uploader(_ uploader: Uploader, didFail error: Error)
}

extension UploaderDelegate {                    // Swift-native "optional" methods
  func uploader(_ uploader: Uploader, didProgress fraction: Double) {}
}

final class Uploader {
  weak var delegate: UploaderDelegate?          // ✅ no retain cycle

  func run(_ file: URL) async {
    do {
      let remote = try await api.upload(file)
      delegate?.uploader(self, didFinish: remote)
    } catch {
      delegate?.uploader(self, didFail: error)
    }
  }
}

final class UploadScreen: UIViewController, UploaderDelegate {
  private let uploader = Uploader()             // screen owns the uploader

  override func viewDidLoad() {
    super.viewDidLoad()
    uploader.delegate = self                    // uploader points back weakly
  }

  func uploader(_ uploader: Uploader, didFinish url: URL) { dismiss(animated: true) }
  func uploader(_ uploader: Uploader, didFail error: Error) { show(error) }
}

