protocol Identified {
  var id: String { get }            // read-only requirement
  var title: String { get set }     // must be writable
  static var kind: String { get }
}

struct Article: Identified {
  let id: String                    // ✅ let satisfies { get }
  var title: String                 // ✅ var satisfies { get set }
  static let kind = "article"       // ✅ static let satisfies a { get } requirement
}

struct Broken: Identified {
  let id: String
  // let title: String              // ❌ let cannot satisfy { get set }
  var title: String { id }          // ❌ get-only computed cannot either
  static let kind = "broken"
}

