// ✅ Fix 3: your own buffer — copy on write
struct Bytes {
  private final class Storage { var data: [UInt8]; init(_ d: [UInt8]) { data = d } }
  private var storage: Storage
  init(_ data: [UInt8]) { storage = Storage(data) }
  mutating func append(_ byte: UInt8) {
    if !isKnownUniquelyReferenced(&storage) { storage = Storage(storage.data) }
    storage.data.append(byte)
  }
}

