class Vehicle {
  var speed: Double = 0                          // the storage lives here, always
  var summary: String { "moving at \(speed)" }
}

final class Train: Vehicle {
  override var speed: Double {                   // ✅ adapt access, delegate storage
    get { super.speed }
    set { super.speed = min(newValue, 300) }     // clamp on the way in
  }
  override var summary: String { "train " + super.summary }
}

class Bus: Vehicle {
  override var speed: Double {                   // ✅ observe an inherited property
    didSet { print("speed is now \(speed), was \(oldValue)") }
  }
}

// ❌ The mistake that looks like it works
class Broken: Vehicle {
  private var mySpeed: Double = 0
  override var speed: Double {
    get { mySpeed }                              // super.speed is never written,
    set { mySpeed = newValue }                   // so `summary` still reports 0
  }
  // override var speed: Double { 42 }           // ❌ read-write cannot become read-only
  // override var speed: Float { 0 }             // ❌ the type must match exactly
}

let bus = Bus()
bus.speed = 80                                   // prints the observer line
print(Broken().speed, Broken().summary)          // 0.0  "moving at 0.0"

extension Vehicle { func honk() { print("beep") } }
class Truck: Vehicle {
  // override func honk() {}                     // ❌ extension members are not overridable
  final override var speed: Double {             // final: no further overrides
    get { super.speed } set { super.speed = newValue }
  }
}

protocol Buildable {
  init(id: String)
}

final class Session: Buildable {            // final: no subclasses, no keyword
  let id: String
  init(id: String) { self.id = id }
}

class Node: Buildable {
  let id: String
  required init(id: String) { self.id = id }   // ✅ every subclass must have it
}

final class Leaf: Node {
  var payload = ""
  // inherits the required init; declaring its own designated init would force
  // it to write `required init(id:)` again
}

struct Tag: Buildable {                     // value types never need `required`
  let id: String
}

// Why the rule exists: T can be bound to a subclass
func make<T: Buildable>(_ type: T.Type, id: String) -> T { type.init(id: id) }
let leaf = make(Leaf.self, id: "1")         // calls the inherited required init

// The same rule, met through Codable
class Animal: Codable {
  var name = ""
}

class Dog: Animal {
  var breed = ""
  private enum CodingKeys: String, CodingKey { case breed }

  required init(from decoder: Decoder) throws {     // ✅ Decodable's init
    let c = try decoder.container(keyedBy: CodingKeys.self)
    breed = try c.decode(String.self, forKey: .breed)
    try super.init(from: decoder)
  }

  override func encode(to encoder: Encoder) throws { // ❌ omit this and breed is lost
    var c = encoder.container(keyedBy: CodingKeys.self)
    try c.encode(breed, forKey: .breed)
    try super.encode(to: encoder)
  }
}

protocol Reloadable { func refresh() }
protocol Pollable { func refresh() }

extension Reloadable { func refresh() { print("from cache") } }
extension Pollable { func refresh() { print("from network") } }

struct Feed: Reloadable, Pollable {
  // Without this line the conformance itself fails: neither default is more
  // specialized, so there is no witness to choose.
  func refresh() { print("feed decides") }   // ✅ the concrete type always wins
}

// Shape 2: the member lives only in extensions
protocol Logging {}
protocol Tracing {}
extension Logging { func emit() { print("log") } }
extension Tracing { func emit() { print("trace") } }

struct Both: Logging, Tracing {}
// Both().emit()                       // ❌ ambiguous use of 'emit()'
(Both() as any Logging).emit()         // ✅ "log" — static dispatch on the cast type

// Specialization the compiler can resolve on its own
protocol Refreshing { func refresh() }
extension Refreshing { func refresh() { print("generic") } }
extension Refreshing where Self: Identifiable { func refresh() { print("by id") } }

struct Row: Refreshing, Identifiable { let id = UUID() }
Row().refresh()                        // "by id" — the constrained extension wins

// A refining protocol beats the protocol it refines
protocol Cached: Refreshing {}
extension Cached { func refresh() { print("cache first") } }

struct Page: Cached, Identifiable { let id = UUID() }
Page().refresh()                       // "cache first"

import System

struct FileHandle: ~Copyable {
  private let fd: Int32

  init(openingAt path: String) throws {
    fd = path.withCString { open($0, O_RDONLY) }
    guard fd >= 0 else { throw Errno(rawValue: errno) }
  }

  borrowing func readByte() -> UInt8? {      // read without taking ownership
    var byte: UInt8 = 0
    return read(fd, &byte, 1) == 1 ? byte : nil
  }

  consuming func close() {
    // Consuming self ends the lifetime here; deinit does the actual close.
  }

  deinit { _ = Darwin.close(fd) }            // deterministic, exactly once
}

func demo() throws {
  let handle = try FileHandle(openingAt: "/etc/hosts")
  _ = handle.readByte()
  let moved = consume handle                 // ownership transferred
  // _ = handle.readByte()                   // ❌ 'handle' used after consume
  moved.close()                              // ❌ using `moved` after this is an error
}

// Generic code has to opt in — a bare <T> still means Copyable
func inspect<T: ~Copyable>(_ value: borrowing T) { print(type(of: value)) }

// Optional composes; Array does not
var slot: FileHandle? = try? FileHandle(openingAt: "/etc/hosts")
slot = nil                                   // deinit runs right here
// var pool: [FileHandle] = []               // ❌ Array requires Copyable elements

// Protocols must allow noncopyable conformers
protocol Closable: ~Copyable { consuming func close() }
extension FileHandle: Closable {}
